//! Text shown by Rust. The Mac's menus, dialogs and window titles come from the catalog's `native`
//! area (`strings_catalog.rs`, generated by `pnpm i18n:apple`) in the language shown: the one the
//! system prefers at launch, chosen as the page chooses it (`resolveLocale`), until Settings picks
//! another (`app_language`). The `devot` command's output stays English, and so does the name a
//! kept-aside mirror file gets, which every device must read back the same.

use std::sync::atomic::{AtomicU8, Ordering};

#[path = "strings_catalog.rs"]
mod catalog;

pub use catalog::Native;

pub const APP_NAME: &str = "Devot";
pub const MIRROR_EDITED_SUFFIX: &str = " (edited outside Devot)";

const UNREAD: u8 = 0;
static SHOWN: AtomicU8 = AtomicU8::new(UNREAD);

/// The native text in the language shown now.
pub fn native() -> &'static Native {
    shown().native()
}

/// The language shown now: the system's until `show` changes it.
pub fn shown() -> Language {
    if let Some(language) = Language::decode(SHOWN.load(Ordering::Acquire)) {
        return language;
    }
    let preferred = language_for(&crate::native::preferred_languages()).encode();
    match SHOWN.compare_exchange(UNREAD, preferred, Ordering::AcqRel, Ordering::Acquire) {
        Ok(_) => Language::decode(preferred),
        Err(other) => Language::decode(other),
    }
    .unwrap_or(Language::English)
}

/// Shows `language` from now on; false when it was shown already.
pub fn show(language: Language) -> bool {
    shown();
    SHOWN.swap(language.encode(), Ordering::AcqRel) != language.encode()
}

/// The first of `preferred` (BCP 47 tags, most preferred first) that has a catalog, else English;
/// Traditional Chinese passes on to the next, since only Simplified ships.
pub fn language_for<S: AsRef<str>>(preferred: &[S]) -> Language {
    preferred
        .iter()
        .find_map(|tag| catalog_language(tag.as_ref()))
        .unwrap_or(Language::English)
}

/// Window titles, which no menu shows: `Note` is also the Format menu's alert.
const WINDOW_TITLES: &[&str] = &["note_window_title", "settings_title", "quick_capture_title"];

/// The menu text `text` in `to`, when it is a text of `from` that every menu field holding it
/// words the same way in `to`; None for any other text, such as a plugin's.
pub fn translate(text: &str, from: &Native, to: &Native) -> Option<&'static str> {
    let mut found = None;
    for ((field, theirs), ours) in Native::FIELDS.into_iter().zip(from.texts()).zip(to.texts()) {
        if theirs != text || WINDOW_TITLES.contains(&field) {
            continue;
        }
        if found.is_some_and(|seen| seen != ours) {
            return None;
        }
        found = Some(ours);
    }
    found
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Language {
    English,
    SimplifiedChinese,
}

impl Language {
    pub fn native(self) -> &'static Native {
        match self {
            Self::English => &catalog::EN,
            Self::SimplifiedChinese => &catalog::ZH_HANS,
        }
    }

    /// The tag the page's `resolveLocale` reads back as this language.
    pub fn tag(self) -> &'static str {
        match self {
            Self::English => "en",
            Self::SimplifiedChinese => "zh-Hans",
        }
    }

    fn encode(self) -> u8 {
        match self {
            Self::English => 1,
            Self::SimplifiedChinese => 2,
        }
    }

    fn decode(code: u8) -> Option<Self> {
        match code {
            1 => Some(Self::English),
            2 => Some(Self::SimplifiedChinese),
            _ => None,
        }
    }
}

/// The shipped language a BCP 47 tag asks for, if any.
pub fn catalog_language(tag: &str) -> Option<Language> {
    let lower = tag.to_ascii_lowercase().replace('_', "-");
    let mut subtags = lower.split('-');
    match subtags.next()? {
        "en" => Some(Language::English),
        "zh" if subtags.any(|s| matches!(s, "hant" | "tw" | "hk" | "mo")) => None,
        "zh" => Some(Language::SimplifiedChinese),
        _ => None,
    }
}

// The `devot` command (`cli`).
pub const CLI_USAGE: &str = "\
Usage:
  devot                                Open Devot, or bring it forward
  devot FILE.md... [--notebook NAME]   Import Markdown files and open the first
  devot export FILE.md|- -o OUT [--simple]
                                       Write a Markdown file (- reads standard
                                       input) as a page, OUT.pdf or OUT.html,
                                       without showing a window
  devot append ID|--title TITLE|--today [--heading H] [--prepend] [--stdin | TEXT]
                                       Add TEXT (or standard input) to a note in
                                       the running Devot: at the end of the
                                       section under heading H, or of the note
  devot mcp                            Serve AI tools over stdio (MCP), through
                                       the running Devot

Options:
  --notebook NAME    Import into the notebook of this name (made when there is
                     none); without it, into the default notebook
  -o, --output OUT   Where export writes: a path ending in .pdf or .html
  --simple           Export bare HTML, without styles (.html only)
  --title TITLE      The note to append to, by its title, instead of its ID
  --today            Append to today's note, made when missing (Settings >
                     General > Daily Notes)
  --heading H        The heading whose section takes the text (any case, with
                     or without its # marks); the note must have it
  --prepend          Put the text at the start of the section instead
  --stdin            Read the text from standard input
  -h, --help         Show this help

Exit status: 0 when done, 1 when it failed, 2 when the command was not
understood.
";
