#[cfg(test)]
mod tests {
    use super::*;

    fn chosen(preferred: &[&str]) -> &'static str {
        language_for(preferred).native().menu_file
    }

    #[test]
    fn follows_the_first_preferred_language_with_a_catalog() {
        let chinese = catalog::ZH_HANS.menu_file;
        assert_eq!(chosen(&[]), "File");
        assert_eq!(chosen(&["en-US"]), "File");
        assert_eq!(chosen(&["zh-Hans-CN", "en"]), chinese);
        assert_eq!(chosen(&["zh-CN"]), chinese);
        assert_eq!(chosen(&["zh_SG"]), chinese);
        assert_eq!(chosen(&["zh"]), chinese);
        assert_eq!(chosen(&["fr-FR", "zh-Hans"]), chinese);
        assert_eq!(chosen(&["fr-FR", "de"]), "File");
    }

    #[test]
    fn passes_traditional_chinese_on_to_the_next_language() {
        assert_eq!(chosen(&["zh-Hant-TW", "en"]), "File");
        assert_eq!(chosen(&["zh-TW"]), "File");
        assert_eq!(chosen(&["zh-HK", "zh-Hans"]), catalog::ZH_HANS.menu_file);
        assert_eq!(chosen(&["zh-MO"]), "File");
    }

    #[test]
    fn translates_a_text_into_the_other_language_by_its_field() {
        let (en, zh) = (&catalog::EN, &catalog::ZH_HANS);
        assert_eq!(translate(en.menu_file, en, zh), Some(zh.menu_file));
        assert_eq!(translate(zh.menu_file, zh, en), Some(en.menu_file));
        assert_eq!(translate(en.quit, en, en), Some(en.quit));
        assert_eq!(translate("My plugin", en, zh), None);
        assert_eq!(
            translate(en.format_alert_note, en, zh),
            Some(zh.format_alert_note)
        );
        for field in WINDOW_TITLES {
            assert!(Native::FIELDS.contains(field), "{field}");
        }
    }

    #[test]
    fn every_menu_text_translates_both_ways() {
        let (en, zh) = (&catalog::EN, &catalog::ZH_HANS);
        let menu_texts = Native::FIELDS
            .into_iter()
            .zip(en.texts().into_iter().zip(zh.texts()))
            .filter(|(field, _)| !WINDOW_TITLES.contains(field));
        for (_, (english, chinese)) in menu_texts {
            assert!(translate(english, en, zh).is_some(), "{english}");
            assert!(translate(chinese, zh, en).is_some(), "{english}");
        }
    }

    #[test]
    fn translates_the_menus() {
        assert_ne!(catalog::ZH_HANS.menu_file, catalog::EN.menu_file);
        assert_eq!(
            catalog::ZH_HANS.startup_folder.matches("{folder}").count(),
            1
        );
        assert_eq!(
            catalog::ZH_HANS
                .plugin_export_note
                .matches("{title}")
                .count(),
            1
        );
    }
}
